def processTaskings(self):
    for task in self.taskings:
        if not task['started']:
            thread = threading.Thread(target=self.execute_task, args=(task,))
            thread.start()

def execute_task(self, task):
    command = task['command']
    params = task['parameters']
    result = eval('self.' + command)(*params)
    task['result'] = result
    task['completed'] = True
    self.postResponses(task)

def getTaskings(self):
  data = {'action': 'get_tasking', 'tasking_size': -1}
  tasking_data = self.postMessageAndRetrieveResponse(data)
  for task in tasking_data['tasks']:
    t = {
      'task_id': task['id'],
      'command': task['command'],
      'parameters': task['parameters'],
      ...
    }
    self.taskings.append(t)

def processTaskings(self):
  for task in self.taskings:
    x = threading.Thread(target=self.processTask, name=..., args=(task,))
    x.start()

